impl markup::Read for ArrayContent {
    fn other(node: xml::element::Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &xml::element::Element) -> Self {
        match markup::name(element) {
            Some((NS_VT, "bstr")) => Self::BasicString(markup::read(element)),
            Some((NS_VT, "bool")) => Self::Boolean(markup::read(element)),
            Some((NS_VT, "cy")) => Self::Currency(markup::read(element)),
            Some((NS_VT, "date")) => Self::DateAndTime(markup::read(element)),
            Some((NS_VT, "decimal")) => Self::Decimal(markup::read(element)),
            Some((NS_VT, "error")) => Self::ErrorStatusCode(markup::read(element)),
            Some((NS_VT, "i1")) => Self::I1(markup::read(element)),
            Some((NS_VT, "i2")) => Self::I2(markup::read(element)),
            Some((NS_VT, "i4")) => Self::I4(markup::read(element)),
            Some((NS_VT, "int")) => Self::Integer(markup::read(element)),
            Some((NS_VT, "r4")) => Self::R4(markup::read(element)),
            Some((NS_VT, "r8")) => Self::R8(markup::read(element)),
            Some((NS_VT, "ui1")) => Self::Ui1(markup::read(element)),
            Some((NS_VT, "ui2")) => Self::Ui2(markup::read(element)),
            Some((NS_VT, "ui4")) => Self::Ui4(markup::read(element)),
            Some((NS_VT, "uint")) => Self::UnsignedInteger(markup::read(element)),
            Some((NS_VT, "variant")) => Self::Variant(markup::read(element)),
            _ => Self::Other(xml::element::Node::Element(element.clone())),
        }
    }
}

impl markup::Write for ArrayContent {
    fn write_into(&self, writer: &mut markup::Writer<'_, '_>) {
        match self {
            Self::BasicString(arm) => arm.write_into(writer),
            Self::Boolean(arm) => arm.write_into(writer),
            Self::Currency(arm) => arm.write_into(writer),
            Self::DateAndTime(arm) => arm.write_into(writer),
            Self::Decimal(arm) => arm.write_into(writer),
            Self::ErrorStatusCode(arm) => arm.write_into(writer),
            Self::I1(arm) => arm.write_into(writer),
            Self::I2(arm) => arm.write_into(writer),
            Self::I4(arm) => arm.write_into(writer),
            Self::Integer(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
            Self::R4(arm) => arm.write_into(writer),
            Self::R8(arm) => arm.write_into(writer),
            Self::Ui1(arm) => arm.write_into(writer),
            Self::Ui2(arm) => arm.write_into(writer),
            Self::Ui4(arm) => arm.write_into(writer),
            Self::UnsignedInteger(arm) => arm.write_into(writer),
            Self::Variant(arm) => arm.write_into(writer),
        }
    }
}

